## Core Win32 APIs for Offensive Development

### Process Creation and Manipulation

```c
#include <windows.h>
#include <stdio.h>

// Basic process creation
int create_process(const char* program) {
    STARTUPINFOA si = {0};
    PROCESS_INFORMATION pi = {0};
    si.cb = sizeof(si);

    // Create a new process
    if (!CreateProcessA(
        NULL,               // Application name
        (LPSTR)program,     // Command line
        NULL,               // Process security attributes
        NULL,               // Thread security attributes
        FALSE,              // Inherit handles
        0,                  // Creation flags
        NULL,               // Environment
        NULL,               // Current directory
        &si,               // Startup info
        &pi               // Process info
    )) {
        printf("CreateProcess failed: %d\n", GetLastError());
        return 1;
    }

    printf("Process created: PID=%d\n", pi.dwProcessId);

    // Wait for process to complete
    WaitForSingleObject(pi.hProcess, INFINITE);

    // Clean up handles
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    return 0;
}
```

### Memory Operations

```c
// Allocate memory in a process (local)
LPVOID mem = VirtualAlloc(
    NULL,                    // Let system choose address
    4096,                    // Size
    MEM_COMMIT | MEM_RESERVE, // Allocation type
    PAGE_EXECUTE_READWRITE   // Protection (RWX - monitored!)
);

// Allocate memory in another process (remote)
HANDLE hProcess = OpenProcess(
    PROCESS_ALL_ACCESS,      // Access rights
    FALSE,                  // Inherit
    targetPid               // Target PID
);

LPVOID remoteMem = VirtualAllocEx(
    hProcess,                // Target process
    NULL,                    // Address (let system choose)
    4096,                    // Size
    MEM_COMMIT | MEM_RESERVE,
    PAGE_EXECUTE_READWRITE  // RWX - heavily monitored!
);
```

### Token Manipulation

```c
// Open a process token
HANDLE hToken;
if (OpenProcessToken(
    GetCurrentProcess(),    // Process handle
    TOKEN_ALL_ACCESS,       // Desired access
    &hToken                // Token handle
)) {
    printf("Got process token\n");
}

// Get token information
DWORD size = 0;
GetTokenInformation(hToken, TokenPrivileges, NULL, 0, &size);
// Allocate buffer and call again with proper size
```

### Error Handling

```c
// Every Win32 API call should be followed by error checking
if (!SomeApiCall(params)) {
    DWORD error = GetLastError();
    LPSTR msg = NULL;
    FormatMessageA(
        FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM,
        NULL, error, 0, (LPSTR)&msg, 0, NULL
    );
    printf("Error %d: %s\n", error, msg);
    LocalFree(msg);
}
```

## Development Environment and OPSEC

### Setting Up a Development Environment

**Visual Studio (Recommended):**
- Community Edition is free for open-source and learning
- Best debugging experience
- Built-in Windows SDK headers and libraries
- CMake support for cross-platform projects

**MinGW-w64 (Alternative):**
```bash
# Install on Linux (for cross-compiling Windows binaries)
sudo apt install mingw-w64

# Compile a Windows executable from Linux
x86_64-w64-mingw32-gcc -o tool.exe tool.c -ladvapi32 -lkernel32

# Compile with no console window
x86_64-w64-mingw32-gcc -o tool.exe tool.c -mwindows
```

### Compiler Options for Offensive Development

```makefile
# MinGW Makefile example
CC = x86_64-w64-mingw32-gcc
CFLAGS = -O2 -Wall -Werror
LDFLAGS = -ladvapi32 -lkernel32 -luser32

# Strip symbols (smaller binary, less analysis surface)
# -s flag strips debug symbols

# Static linking (no DLL dependencies, but larger binary)
# -static flag

tool.exe: tool.c
	$(CC) $(CFLAGS) -s -o $@ $< $(LDFLAGS)
```

### OPSEC Considerations for Tool Development

| Consideration | Poor OPSEC | Good OPSEC |
|--------------|-----------|-----------|
| API calls | Direct calls to known APIs | Indirect calls, dynamic resolution |
| Strings | Hardcoded strings in binary | Encrypted/obfuscated strings |
| Memory | RWX pages | RX + RW pages separately |
| Network | Direct C2 connection | Domain fronting, proxy aware |
| Artifacts | Default compiler output | Custom compilation, symbol stripping |
| IOCs | Known patterns | Unique per-operation |

### String Obfuscation Example

```c
// Poor: Plaintext strings visible in binary
char* cmd = "cmd.exe";

// Better: XOR-encrypted strings
decrypt_string(encrypted_cmd, key, buffer, sizeof(buffer));

// Best: Generated at runtime, never stored in binary
void build_command(wchar_t* buf, int len) {
    // Build string from individual chars
    buf[0] = L'c'; buf[1] = L'm'; buf[2] = L'd';
    buf[3] = L'.'; buf[4] = L'e'; buf[5] = L'x'; buf[6] = L'e';
    buf[7] = L'\0';
}
```

### Dynamic API Resolution

```c
// Poor: Direct API call (hooked by EDR)
CreateRemoteThread(hProcess, ...);

// Better: Dynamic resolution
typedef HANDLE (WINAPI* pCreateRemoteThread)(
    HANDLE, LPSECURITY_ATTRIBUTES, SIZE_T,
    LPTHREAD_START_ROUTINE, LPVOID, DWORD, LPDWORD
);

HMODULE hKernel32 = LoadLibraryA("kernel32.dll");
pCreateRemoteThread fCreateRemoteThread = 
    (pCreateRemoteThread)GetProcAddress(hKernel32, "CreateRemoteThread");

if (fCreateRemoteThread) {
    fCreateRemoteThread(hProcess, ...);
}
```
